import { isAdmin, type AdminResponse } from '#shared/types/note'

export default defineEventHandler((event): AdminResponse => {
  const name = currentUser(event)
  if (!name || !isAdmin(name)) return { name, allowed: false, users: [] }
  return { name, allowed: true, users: listUsers() }
})

