/** Fields a value needs quoting for: comma, double quote, or either line break. */
const CSV_NEEDS_QUOTES = /[",\n\r]/

function csvField(value: string): string {
  return CSV_NEEDS_QUOTES.test(value) ? `"${value.replace(/"/g, '""')}"` : value
}

function toCsv(notes: { number: number; title: string; body: string; pinned: boolean; archived: boolean; createdAt: string }[]): string {
  const lines = [
    'number,title,body,pinned,archived,createdAt',
    ...notes.map((note) =>
      [String(note.number), csvField(note.title), csvField(note.body), String(note.pinned), String(note.archived), note.createdAt].join(','),
    ),
  ]
  return lines.map((line) => `${line}\r\n`).join('')
}

/** The signed-in user's own notes (archived included, shared-with-me excluded) as a JSON or CSV download. */
export default defineEventHandler((event) => {
  const name = currentUser(event)
  if (!name) throw createError({ statusCode: 401, statusMessage: 'Not signed in' })

  const format = String(getQuery(event).format ?? 'json')
  if (format !== 'json' && format !== 'csv') throw createError({ statusCode: 400, statusMessage: 'Invalid format' })

  const notes = listOwnNotes(name).map((note) => ({
    number: note.number,
    title: note.title,
    body: note.body,
    pinned: note.pinned,
    archived: note.archived,
    createdAt: new Date(note.createdAt).toISOString(),
  }))

  setResponseHeader(event, 'content-disposition', `attachment; filename="notes-${name}.${format}"`)

  if (format === 'csv') {
    setResponseHeader(event, 'content-type', 'text/csv')
    return toCsv(notes)
  }

  setResponseHeader(event, 'content-type', 'application/json')
  return { user: name, notes }
})

